css:
.rc { width: 72mm; margin: 0 auto; color:#000; background:#fff; font-family:"Helvetica Neue",Arial,sans-serif; font-size:11px; line-height:1.4; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.rc * { box-sizing: border-box; }
.rc .mono { font-family:"Courier New",ui-monospace,monospace; }
.rc-head { text-align:center; padding-bottom:3px; }
.rc-logo { max-height:34px; max-width:55%; display:block; margin:0 auto 3px; filter:grayscale(1) contrast(1.5); }
.rc-inst { font-weight:700; font-size:13px; text-transform:uppercase; letter-spacing:.3px; }
.rc-college { font-size:10px; margin-top:1px; }
.rc-title { text-align:center; font-weight:700; font-size:12px; letter-spacing:1.5px; border-top:1.5px solid #000; border-bottom:1.5px solid #000; padding:3px 0; margin:5px 0; }
.rc-meta { display:flex; justify-content:space-between; font-size:9.5px; margin-bottom:5px; }
.rc-name { text-align:center; font-weight:700; font-size:15px; letter-spacing:.3px; margin-bottom:5px; }
.rc-rows { border-top:1px dashed #000; padding-top:4px; }
.rc-rows .r { display:flex; justify-content:space-between; gap:10px; padding:1.5px 0; }
.rc-rows .k { font-weight:600; white-space:nowrap; }
.rc-rows .v { text-align:right; overflow-wrap:anywhere; }
.rc-amount { display:flex; justify-content:space-between; align-items:center; border-top:1px dashed #000; border-bottom:1px dashed #000; margin-top:6px; padding:5px 2px; font-weight:700; }
.rc-amount .lbl { letter-spacing:1.5px; font-size:11px; }
.rc-amount .val { font-size:16px; }
.rc-foot { text-align:center; font-size:9px; line-height:1.3; margin-top:12px; padding-top:4px; border-top:1px dashed #000; }
@media print { @page { size:80mm auto; margin:3mm; } html, body { width:80mm; margin:0 !important; padding:0 !important; background:#fff; } }
